path = "french_dict.json"
with open(path, encoding="utf-8") as f:
    existing = json.load(f)

existing_fr = {d["fr"] for d in existing}
merged = list(existing)  # 保留已有顺序（已按频率在前）
for fr, zh in ADD:
    if fr in existing_fr:
        continue
    existing_fr.add(fr)
    merged.append({"fr": fr, "zh": zh, "rank": 0, "present": []})

# 重排 rank（保持顺序，高频在前）
for i, d in enumerate(merged, 1):
    d["rank"] = i

# 截断到约 540 条以贴合“约 500 个最常用”
LIMIT = 540
merged = merged[:LIMIT]

with open(path, "w", encoding="utf-8") as f:
    json.dump(merged, f, ensure_ascii=False, indent=1)

